-- The Head Office employee directory, as supplied in "Employee Database.xlsx" (354 people).
--
-- Columns taken, in the order the file gives them: Name, Employee ID, Company Email, Department,
-- Designation, Official Phone Number, Location. Salary Unit is deliberately not imported.
--
-- Five rows arrive inactive, because an inactive employee is never mailed and these four cannot
-- be, while the fifth would double a delivery:
--   000025 Md. Abul Kashem, 000398 A.Q.M. Sahiduzzaman, 000168 J Hasan -- no address on file
--   010744 Md. Shariful Islam -- the address on file, "sharifrohan123@gmail", has no domain
--   000688 Mohammed Shamsul Alam -- shares shamsul.alam2@anwargroup.net with 000636
-- All five are in the directory and a System Admin can fix the address and switch them on.

-- What the demo left behind. Rows that someone signs in with, and rows that orders, collections
-- or reports still point at, are kept: deleting them would lock people out and tear holes in the
-- history. Everything else was seed data for a directory that now has a real one.
delete from employees e
where e.account_status is null
  and e.deleted_at is null
  and not exists (select 1 from orders o where o.employee_id = e.id)
  and not exists (select 1 from cancellation_requests c where c.employee_id = e.id);

create temporary table directory_import (
  id          text primary key,
  name        text not null,
  email       text not null,
  phone       text not null,
  department  text not null,
  designation text not null,
  active      boolean not null
);


-- Everyone in the file. Location is "Head Office" for all 354, and is stored in `site`, which is
-- the column the rest of the system already reads as where someone collects.
select i.id, i.name, i.email, i.phone, i.department, i.designation, 'Head Office', i.active
from directory_import i
on conflict (id) do update set
  name        = excluded.name,
  phone       = excluded.phone,
  department  = excluded.department,
  designation = excluded.designation,
  site        = excluded.site,
  -- Someone who signed up before the import already holds this employee ID. The directory
  -- refreshes their details, but not the address they sign in with and not whether their account
  -- is switched on -- the file is a directory, not an instruction to change someone's access.
  company_email = case when employees.account_status is null
                       then excluded.company_email else employees.company_email end,
  active        = case when employees.account_status is null
                       then excluded.active else employees.active end,
  updated_at  = now();

-- Booking is what the directory is for, so every person in it holds the employee role. It does
-- not let them sign in: that needs account_status, which these rows don't have (migration 0002).
-- It is what lets the link mailed to them open a booking session and place an order in their name.
select i.id, 'employee', 'Employee Database import'
from directory_import i
on conflict do nothing;

drop table directory_import;
